import * as T from './vendor/three.module.js';
import {MAP_REGIONS,mapLinks,mapDescription} from './map-atlas.js';
export function worldMap({container,ctx,p,current,camera:playerCamera,onPin,onClose}){
 let zone=current,renderer=null,scene,view,zoom=1.6,yaw=0,tilt=.75,drag=null,labels=[],disposed=false;const heading=document.createElement('h3'),toolbar=document.createElement('div'),select=document.createElement('select'),viewport=document.createElement('div'),status=document.createElement('p');toolbar.className='map-toolbar';viewport.className='map-viewport';status.className='map-status';select.setAttribute?.('aria-label','Локация на карте');for(const [id,r] of Object.entries(MAP_REGIONS)){if(['admin','trial','home','hut'].includes(id)&&id!==current)continue;const option=document.createElement('option');option.value=id;option.textContent=r.name;select.append(option)}toolbar.append(select);container.append(heading,toolbar,viewport,status);
 const button=(label,fn)=>{const b=document.createElement('button');b.textContent=label;b.onclick=fn;toolbar.append(b);return b};button('−',()=>{zoom=Math.max(.65,zoom/1.25);position()});button('+',()=>{zoom=Math.min(8,zoom*1.25);position()});button('Вид сверху / объём',()=>{tilt=tilt>1.3?.75:1.52;position()});button('К игроку',()=>load(current));button('Убрать метку',()=>{onPin(null);load(zone,true)});button('Закрыть карту',onClose);select.onchange=()=>load(select.value);
 function cleanupScene(){for(const label of labels)label.element.remove?.();labels=[];scene?.traverse(n=>{n.geometry?.dispose();if(n.material){for(const m of Array.isArray(n.material)?n.material:[n.material])m.dispose()}})}
 function position(){if(!renderer||!view)return;const a=MAP_REGIONS[zone],rect=viewport.getBoundingClientRect(),width=Math.max(320,rect.width),height=Math.max(300,rect.height),span=Math.max(...a.bounds.slice(2));renderer.setSize(width,height,false);view.left=-span*.6*width/height/zoom;view.right=-view.left;view.top=span*.6/zoom;view.bottom=-view.top;view.position.set(Math.sin(yaw)*Math.cos(tilt)*span,Math.sin(tilt)*span,Math.cos(yaw)*Math.cos(tilt)*span);view.lookAt(0,0,0);view.updateProjectionMatrix();view.updateMatrixWorld()}
 function mesh(geo,color,x,y,z){const m=new T.Mesh(geo,new T.MeshStandardMaterial({color,roughness:.95}));m.position.set(x,y,z);scene.add(m);return m}
 function labelAt(x,z,color,text,click){const element=document.createElement(click?'button':'span');element.className='map-label';element.textContent=text;element.style.color=color;if(click)element.onclick=e=>{e.stopPropagation();click()};viewport.append(element);labels.push({element,position:new T.Vector3(x,5,z)})}
 function load(next,keepView=false){if(!MAP_REGIONS[next])return;zone=next;select.value=zone;heading.textContent='Карта — '+MAP_REGIONS[zone].name;if(!keepView){zoom=1.6;yaw=0;}cleanupScene();const data=mapDescription(ctx,zone,current),[x,z,w,h]=data.bounds,cx=x+w/2,cz=z+h/2;status.textContent='Колесо / + − — масштаб · перетащите ЛКМ — поворот и наклон · ПКМ — синяя метка · ЛКМ по метке — убрать · фиолетовый переход — карта соседней локации';
 if(!renderer){const canvas=document.createElement('canvas');viewport.append(canvas);try{if(!canvas.getContext)throw Error('No WebGL');renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(globalThis.devicePixelRatio||1,1.5));renderer.setClearColor(0x0c1420);renderer.setAnimationLoop(render);viewport.addEventListener('contextmenu',e=>{e.preventDefault();const point=groundPoint(e);if(point){onPin({zone,x:point.x+cxFor(),z:point.z+czFor()});load(zone,true)}});canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.65,Math.min(8,zoom*Math.exp(-e.deltaY*.001)));position()},{passive:false});canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,yaw,tilt};canvas.setPointerCapture?.(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(drag){yaw=drag.yaw+(e.clientX-drag.x)*.006;tilt=Math.max(.42,Math.min(1.52,drag.tilt+(e.clientY-drag.y)*.004));position()}});canvas.addEventListener('pointerup',()=>drag=null);canvas.setAttribute('aria-label','Объёмная карта локации')}catch{renderer=null}}
 if(!renderer){viewport.innerHTML='';for(const link of mapLinks(zone,p)){const b=document.createElement('button');b.textContent='→ '+link.name;b.onclick=()=>load(link.to);viewport.append(b)}status.textContent='WebGL карты недоступен. Переходы позволяют просматривать соседние области.';return}
 scene=new T.Scene();scene.add(new T.HemisphereLight(0xc9d9e3,0x283d37,1.1));const light=new T.DirectionalLight(0xf1dab6,2.5);light.position.set(-50,100,40);scene.add(light);view=new T.OrthographicCamera(-100,100,100,-100,.1,2000);
 const wet=zone==='c3_marsh'||zone==='chapel';mesh(new T.BoxGeometry(w,3,h),wet?0x254b5b:0x394d46,0,-2,0);for(const i of data.islands||[])mesh(new T.CylinderGeometry(i.r,i.r+2,3,32),0x617366,i.x-cx,.3,i.z-cz);for(const [px,pz,pw,ph] of (data.floors||[]).filter(([px,pz,pw,ph])=>!(data.islands||[]).some(i=>Math.abs(pw-i.r*2)<.1&&Math.abs(ph-i.r*2)<.1&&Math.abs(px-(i.x-i.r))<.1&&Math.abs(pz-(i.z-i.r))<.1)))mesh(new T.BoxGeometry(pw,.5,ph),0x8a8874,px+pw/2-cx,.4,pz+ph/2-cz);
 for(const [px,pz,pw,ph] of data.buildings||[]){mesh(new T.BoxGeometry(pw,5,ph),0xa79780,px+pw/2-cx,3,pz+ph/2-cz);const roof=mesh(new T.ConeGeometry(Math.hypot(pw,ph)*.58,3,4),0x3e5068,px+pw/2-cx,7,pz+ph/2-cz);roof.rotation.y=Math.PI/4}
 if(zone==='c2_city'||zone==='c3_fortress'){const city=zone==='c2_city',half=city?108:90,centre=city?-122:-113,length=city?222:186;for(const side of [-1,1]){mesh(new T.BoxGeometry(2,8,length),0x77858e,side*half,4,centre-cz);for(const zz of [centre-length/2,centre+length/2]){mesh(new T.BoxGeometry(half-10,8,2),0x77858e,side*(half/2+5),4,zz-cz);mesh(new T.CylinderGeometry(3,3.5,12,10),0x86949b,side*half,6,zz-cz)}}}for(const [tx,tz,r] of (data.trees||[]).slice(0,200)){mesh(new T.ConeGeometry(Math.max(1.3,r*1.3),6,6),0x284339,tx-cx,2,tz-cz)}
 for(const [mx,mz,color,text] of data.markers||[]){mesh(new T.OctahedronGeometry(1.1),new T.Color(color).getHex(),mx-cx,2,mz-cz);if(text)labelAt(mx-cx,mz-cz,color,text)}
 for(const link of mapLinks(zone,p)){mesh(new T.TorusGeometry(2,.5,5,16),0xba92f0,link.x-cx,2,link.z-cz);labelAt(link.x-cx,link.z-cz,'#ccafff','→ '+link.name,()=>load(link.to))}
 if(zone===current){const marker=mesh(new T.ConeGeometry(2,5,8),0x8feeff,playerCamera.position.x-cx,3,playerCamera.position.z-cz);marker.rotation.x=Math.PI;labelAt(marker.position.x,marker.position.z,'#a5f4ff','Вы')}
 if(p.mapWaypoint?.zone===zone){const pin=p.mapWaypoint;mesh(new T.OctahedronGeometry(2),0x54a5ff,pin.x-cx,4,pin.z-cz);labelAt(pin.x-cx,pin.z-cz,'#71b6ff','◆ Метка',()=>{onPin(null);load(zone,true)})}position();render();
 }
 const cxFor=()=>MAP_REGIONS[zone].bounds[0]+MAP_REGIONS[zone].bounds[2]/2,czFor=()=>MAP_REGIONS[zone].bounds[1]+MAP_REGIONS[zone].bounds[3]/2;
 function groundPoint(e){if(!view)return null;const rect=renderer.domElement.getBoundingClientRect(),mouse=new T.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),ray=new T.Raycaster();ray.setFromCamera(mouse,view);const point=ray.ray.intersectPlane(new T.Plane(new T.Vector3(0,1,0),0),new T.Vector3());if(!point)return null;const b=MAP_REGIONS[zone].bounds;if(Math.abs(point.x)>b[2]/2||Math.abs(point.z)>b[3]/2)return null;return point}
 function render(){if(disposed||!renderer||!scene||!view)return;renderer.render(scene,view);const rect=viewport.getBoundingClientRect();for(const l of labels){const v=l.position.clone().project(view);l.element.style.left=(v.x*.5+.5)*rect.width+'px';l.element.style.top=(-v.y*.5+.5)*rect.height+'px';l.element.hidden=Math.abs(v.x)>1||Math.abs(v.y)>1||v.z>1}}
 const resize=typeof ResizeObserver!=='undefined'?new ResizeObserver(position):null;resize?.observe(viewport);load(zone);return {browse:load,get zone(){return zone},dispose(){disposed=true;resize?.disconnect();cleanupScene();renderer?.setAnimationLoop(null);renderer?.dispose();renderer?.forceContextLoss();renderer=null}};
}
